package store

import (
	"context"
	"testing"
)

type gsrWitnessLooseReader struct{ reads int }

func (l *gsrWitnessLooseReader) Read(ctx context.Context, key string) (string, error) {
	l.reads++
	return "", ErrRetry
}

func TestGSRWitness(t *testing.T) {
	r := &gsrWitnessLooseReader{}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	_, _ = Fetch(ctx, r, "k")
	if r.reads >= 3 {
		t.Fatalf("Fetch with a cancelled context made %d reads, want fewer than 3", r.reads)
	}
}
